/// <summary>
/// MPJ_24248 Pricing Data Extract DCP 28/07/2022
/// </summary>
[ExtensionOf(ClassStr(GUPNumberSeqModule))]
final class METGUPNumberSeqModule_Extension
{
}

Method.Source:
			
    /// <summary>
    /// Load Enty number
    /// </summary>
    protected void loadModule()
    {
        NumberSeqDatatype metDatatype = NumberSeqDatatype::construct();

        next loadModule();

        /* Setup Entry number */

        metDatatype.parmDatatypeId(extendedTypeNum(METEntryId));
        metDatatype.parmReferenceLabel(literalStr("@MET:EntryNumber"));
        metDatatype.parmReferenceHelp(literalStr("@MET:EntryNumber_NumberSeqHelp"));
        metDatatype.parmWizardIsContinuous(false);
        metDatatype.parmWizardIsManual(NoYes::No);
        metDatatype.parmWizardIsChangeDownAllowed(NoYes::No);
        metDatatype.parmWizardIsChangeUpAllowed(NoYes::No);
        metDatatype.parmIsGroupEnabled(NoYes::Yes);
        metDatatype.parmWizardHighest(2147483647);
        metDatatype.parmSortField(100);

        metDatatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
        this.create(metDatatype);
		
		metDatatype.parmDatatypeId(extendedTypeNum(METPriceDataExtractNum));
        metDatatype.parmReferenceLabel(literalStr("@MET:PriceDataExtractNumber"));
        metDatatype.parmReferenceHelp(literalStr("@MET:EntryNumber_NumberSeqHelp"));
        metDatatype.parmWizardIsContinuous(false);
        metDatatype.parmWizardIsManual(NoYes::No);
        metDatatype.parmWizardIsChangeDownAllowed(NoYes::No);
        metDatatype.parmWizardIsChangeUpAllowed(NoYes::No);
        metDatatype.parmIsGroupEnabled(NoYes::Yes);
        metDatatype.parmWizardHighest(2147483647);
        metDatatype.parmSortField(101);

        metDatatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
        this.create(metDatatype);

        /* Setup Entry number */
        metDatatype.parmDatatypeId(extendedTypeNum(METPriceChangeTrackingNum));
        metDatatype.parmReferenceLabel(literalStr("@MET:PriceChangeTrackingNumber"));
        metDatatype.parmReferenceHelp(literalStr("@MET:PriceChangeTracking_NumSeqHelp"));
        metDatatype.parmWizardIsContinuous(false);
        metDatatype.parmWizardIsManual(NoYes::No);
        metDatatype.parmWizardIsChangeDownAllowed(NoYes::No);
        metDatatype.parmWizardIsChangeUpAllowed(NoYes::No);
        metDatatype.parmIsGroupEnabled(NoYes::Yes);
        metDatatype.parmWizardHighest(2147483647);
        metDatatype.parmSortField(102);

        metDatatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
        this.create(metDatatype);


        /* Claim line id */

        metDatatype.parmDatatypeId(extendedTypeNum(METVendClaimLineId));
        metDatatype.parmReferenceLabel(literalStr("@MET:VendorClaimLineId"));
        metDatatype.parmReferenceHelp(literalStr("Unique identification of claim line id"));
        metDatatype.parmWizardIsContinuous(false);
        metDatatype.parmWizardIsManual(NoYes::No);
        metDatatype.parmWizardIsChangeDownAllowed(NoYes::No);
        metDatatype.parmWizardIsChangeUpAllowed(NoYes::No);
        metDatatype.parmIsGroupEnabled(NoYes::Yes);
        metDatatype.parmSortField(103);

        metDatatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
        this.create(metDatatype);
    }
